import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r


def build_brute(inorder, postorder):
    if not inorder:
        return None
    root_v = postorder[-1]
    root = T(root_v)
    k = inorder.index(root_v)
    root.l = build_brute(inorder[:k], postorder[:k])
    root.r = build_brute(inorder[k + 1:], postorder[k:-1])
    return root


def level_order(root):
    if not root:
        return ''
    q = deque([root])
    res = []
    while q:
        node = q.popleft()
        if node is None:
            res.append('n')
        else:
            res.append(str(node.v))
            q.append(node.l)
            q.append(node.r)
    while res and res[-1] == 'n':
        res.pop()
    return ' '.join(res)


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    inorder = list(map(int, data[1:1 + n]))
    postorder = list(map(int, data[1 + n:1 + 2 * n]))
    root = build_brute(inorder, postorder)
    print(level_order(root))

