import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r


def build_best(inorder, postorder):
    pos = {v: i for i, v in enumerate(inorder)}
    idx = len(postorder) - 1

    def rec(il, ir):
        nonlocal idx
        if il > ir:
            return None
        root_v = postorder[idx]
        idx -= 1
        root = T(root_v)
        k = pos[root_v]
        root.r = rec(k + 1, ir)
        root.l = rec(il, k - 1)
        return root

    return rec(0, len(inorder) - 1)


def level_order(root):
    if not root:
        return ''
    q = deque([root])
    res = []
    while q:
        node = q.popleft()
        if node is None:
            res.append('n')
        else:
            res.append(str(node.v))
            q.append(node.l)
            q.append(node.r)
    while res and res[-1] == 'n':
        res.pop()
    return ' '.join(res)


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    inorder = list(map(int, data[1:1 + n]))
    postorder = list(map(int, data[1 + n:1 + 2 * n]))
    root = build_best(inorder, postorder)
    print(level_order(root))
